'''Completer for a list of key-value pairs, generated by a command.'''

from ..bash_complete import BashCompletionFunc
from ..fish_complete import FishCompletionCommand
from ..zsh_complete import ZshComplFunc
from ..scheme_validator import (
    check_type, check_char, check_non_empty_string)
from ..helpers import ShellFunction
from ..helpers import FishFunction
from ..bash_helpers import BashHelpers
from ..fish_helpers import FishHelpers
from ..zsh_helpers import ZshHelpers

CATEGORY = 'custom'

SYNOPSIS = r'''
['key_value_list_exec', <PAIR_SEPARATOR>, <VALUE_SEPARATOR>, <COMMAND>]
'''

SHORT = 'Complete dynamically generated comma-separted lists of key=value pairs'

LONG = r'''
`PAIR_SEPARATOR`:
  The separator used to separate individual key-value pairs.

`VALUE_SEPARATOR`:
  The separator used to separate a key from its value.

`COMMAND`:
  The command or function used to generate the available keys and values.

  If invoked without arguments, it must output the available keys in the
  following format:

  ```
  [*]<KEY_1>[=][?]\t<DESCRIPTION_1>\t<EXCLUDES>
  [*]<KEY_2>[=][?]\t<DESCRIPTION_2>\t<EXCLUDES>
  [...]
  ```

  Prefixing a key with `*` marks it as repeatable.

  Appending `=` to a key indicates that it requires a value.

  Appending `=?` to a key indicates that it requires an optional value.

  `EXCLUDES` is a space-separated list of keys that should no longer be
  offered once the current key has been used.

  If invoked with a single argument, the argument is the selected key.
  The command must output the possible values for that key in the following
  format:

  ```
  <ITEM_1>\t<DESCRIPTION_1>
  <ITEM_2>\t<DESCRIPTION_2>
  [...]
  ```

  Each line represents one completion candidate. The item and its description
  are separated by a tab character.

Example function:

```sh
_complete_key_value_list() {
  if (( $# == 0 )); then
    printf '%s\t%s\t%s\n'                                 \
      'flag'        'option without an argument'       '' \
      'argument='   'option with an argument'          '' \
      'optional=?'  'option with an optional argument' '' \
      '*repeatable' 'a repeatable option'              '' \
      'excludes'    'disable options'                  'flag argument'
  else
    case '$1' in
      argument|optional)
        printf '%s\t%s\n'     \
          'foo' 'a foo value' \
          'bar' 'a bar value';;
      esac
  fi
}
```
'''

ALSO = {
    'key_value_list': 'For completing comma-separated lists of key=value pairs',
}

NOTES = [
    'Functions can be put inside a file and included with `--include-file`',
]

DEFINITION = r'''
prog: 'example'
options:
  - option_strings: ['-o']
    complete: ['key_value_list_exec', ',', '=', '_complete_key_value_list']
'''

OUTPUT = r'''
~ > example -o <TAB>
argument      -- option with an argument
excludes      -- disable options
flag          -- option without an argument
optional      -- option with an optional argument
repeatable    -- a repeatable option

~ > example -o argument=<TAB>
foo    -- a foo value
bar    -- a bar value

~ > example -o excludes,<TAB>
optional    -- option with an optional argument
repeatable  -- a repeatable option
'''

_KEY_VALUE_LIST_EXEC_BASH = ShellFunction('key_value_list_exec', r'''
local sep1="$1"
local sep2="$2"
local func="$3"
local -A excludes=()
local -A takes_arg=()
local key desc exclude non_repeatable_exclude

while IFS=$'\t' read -r key desc exclude; do
  local has_arg=false

  if [[ "$key" == *'=' ]]; then
    key="${key:0:-1}"
    has_arg=true
  elif [[ "$key" == *'=?' ]]; then
    key="${key:0:-2}"
  fi

  if [[ "$key" == '*'* ]]; then
    key="${key:1}"
    non_repeatable_exclude=''
  else
    non_repeatable_exclude=" $key"
  fi

  takes_arg[$key]=$has_arg
  excludes[$key]="$exclude$non_repeatable_exclude"
done < <($func)

local strip_chars=''
[[ "$COMP_WORDBREAKS" == *"$sep1"* ]] && strip_chars+="$sep1"
[[ "$COMP_WORDBREAKS" == *"$sep2"* ]] && strip_chars+="$sep2"
[[ "${cur:0:1}" == '"' ]] && strip_chars=''
[[ "${cur:0:1}" == "'" ]] && strip_chars=''
local cur="$cur" break_pos in_quotes
dequote "$cur" cur break_pos in_quotes

if [[ -z "$cur" ]]; then
  COMPREPLY=("${!excludes[@]}")
  return
fi

local pair key value found_key cur_stripped="$cur"
local -a tmp having_pairs having_keys remaining_keys

IFS="$sep1" read -r -a having_pairs <<< "$cur"

for pair in "${having_pairs[@]}"; do
  key="${pair%%"$sep2"*}"
  IFS=' ' read -r -a tmp <<< "${excludes[$key]}"
  having_keys+=("${tmp[@]}")
done

for key in "${!excludes[@]}"; do
  found_key=0

  for having_key in "${having_keys[@]}"; do
    if [[ "$key" == "$having_key" ]]; then
      found_key=1
      break
    fi
  done

  if (( ! found_key )); then
    remaining_keys+=("$key")
  fi
done

COMPREPLY=()

if [[ "${cur: -1}" == "$sep1" ]]; then
  [[ -n "$strip_chars" ]] && cur_stripped="${cur_stripped##*[$strip_chars]}"

  for key in "${remaining_keys[@]}"; do
    COMPREPLY+=("$cur_stripped$key")
  done
else
  pair="${cur##*"$sep1"}"
  if [[ "$pair" == *"$sep2"* ]]; then
    key="${pair%%"$sep2"*}"
    value="${pair#*"$sep2"}"
    cur="$value"
    exec "$func $key"

    cur_stripped="${cur_stripped:0:$(( ${#cur_stripped} - ${#value} ))}"
    if [[ -n "$strip_chars" ]]; then
        cur_stripped="${cur_stripped##*[$strip_chars]}"
    fi

    for i in "${!COMPREPLY[@]}"; do
      COMPREPLY[i]="$cur_stripped${COMPREPLY[i]}"
    done
  else
    [[ -n "$strip_chars" ]] && cur_stripped="${cur_stripped##*[$strip_chars]}"
    cur_stripped="${cur_stripped%"$pair"}"

    for key in "${remaining_keys[@]}"; do
      if [[ "$key" == "$pair"* ]]; then
        COMPREPLY+=("$cur_stripped$key")
      fi
    done
  fi
fi
''', ['dequote', 'exec'])

_KEY_VALUE_LIST_EXEC_FISH = FishFunction('key_value_list_exec', r'''
set -l sep1 $argv[1]
set -l sep2 $argv[2]
set -l func $argv[3]
set -l comp (get_completing_arg)
set -l pairs (string split -- $sep1 $comp)

set -l keys
set -l descriptions
set -l takes_arg
set -l excludes

set -l line
set -l i

for line in ($func)
  set -l split (string split -- \t $line)
  set -l key $split[1]
  set -l non_repeatable_exclude ''

  if string match -qr -- '=$' $key
    set key (string sub -e -1 -- $key)
    set -a takes_arg true
  else if string match -qr -- '=\?$' $key
    set key (string sub -e -2 -- $key)
    set -a takes_arg false
  else
    set -a takes_arg false
  end

  if string match -q -- '\**' $key
    set key (string sub -s 2 -- $key)
  else
    set non_repeatable_exclude " $key"
  end

  set -a keys $key
  set -a descriptions $split[2]
  set -a excludes "$split[3]$non_repeatable_exclude"
end

set -l remaining (seq 1 (count $keys))

set -l pair
for pair in $pairs
  set -l split (string split -m1 -- $sep2 $pair)
  set i (contains -i -- $split[1] $keys)

  if test $status -eq 0
    set -l exclude
    for exclude in (string split -n -- ' ' $excludes[$i])
      set i (contains -i -- $exclude $keys)
      if test $status -eq 0
        set remaining (string match -v $i -- $remaining)
      end
    end
  end
end

if test -z "$comp" || test (string sub -s -1 -l 1 -- $comp) = $sep1
  for i in $remaining
    if test "$takes_arg[$i]" = false
      printf '%s%s\t%s\n' "$comp" $keys[$i] "$descriptions[$i]"
    else
      printf '%s%s%s\t%s\n' "$comp" $keys[$i] $sep2 "$descriptions[$i]"
    end
  end
  return
end

set -l pair $pairs[-1]
set -l split (string split -m1 -- $sep2 $pair)

switch $pair
  case "*$sep2*"
    set -l value_len (string length -- $split[2])

    if test $value_len -gt 0
      set comp (string sub -e -$value_len -- $comp)
    end

    set -g __fish_stripprefix "^.*"(string escape --style=regex -- $sep)
    for value in ($func $split[1])
      printf '%s%s\n' $comp $value
    end
    set -e __fish_stripprefix
  case '*'
    set -l key_len (string length -- $split[1])
    set comp (string sub -e -$key_len -- $comp)

    for i in $remaining
      if test "$takes_arg[$i]" = false
        printf '%s%s\t%s\n' "$comp" $keys[$i] "$descriptions[$i]"
      else
        printf '%s%s%s\t%s\n' "$comp" $keys[$i] $sep2 "$descriptions[$i]"
      end
    end
end
''', ['get_completing_arg'])

_KEY_VALUE_LIST_EXEC_ZSH = ShellFunction('key_value_list_exec', r'''
local sep1="$1"
local sep2="$2"
local func="$3"
local key='' desc='' excludes=''
local -a args=()

while IFS=$'\t' read -r key desc excludes; do
  desc="${desc//\\/\\\\}"
  desc="${desc//:/\\:}"
  desc="${desc//\[/\\[}"
  desc="${desc//\]/\\]}"

  [[ -n "$excludes" ]] && excludes="($excludes)"

  if [[ "${key: -1:1}" == '=' ]]; then
    key="${key:0:-1}"
    args+=("${excludes}${key}[$desc]: :{exec '$func $key'}")
  elif [[ "${key: -2:2}" == '=?' ]]; then
    key="${key:0:-2}"
    args+=("${excludes}${key}[$desc]:: :{exec '$func $key'}")
  else
    args+=("${excludes}${key}[$desc]")
  fi
done < <(eval "$func")

_values -s "$sep1" -S "$sep2" '' "${args[@]}"
''', ['exec'])

BashHelpers.add_function(_KEY_VALUE_LIST_EXEC_BASH)
FishHelpers.add_function(_KEY_VALUE_LIST_EXEC_FISH)
ZshHelpers.add_function(_KEY_VALUE_LIST_EXEC_ZSH)


def validate(_ctxt, arguments):
    '''Validate YAML for key_value_list_exec completer'''
    pair_separator = arguments.get_required_arg('pair_separator')
    value_separator = arguments.get_required_arg('value_separator')
    command = arguments.get_required_arg('command')
    arguments.require_no_more()

    check_type(pair_separator, (str,), 'pair_separator')
    check_type(value_separator, (str,), 'value_separator')
    check_char(pair_separator, 'pair_separator')
    check_char(value_separator, 'value_separator')
    check_type(command, (str,), 'command')
    check_non_empty_string(command, 'command')


def bash(_completer, ctxt, _trace, pair_separator, value_separator, command):
    '''Implement key_value_list_exec for bash'''
    func = ctxt.helpers.use_function('key_value_list_exec')
    return BashCompletionFunc(
        ctxt, [func, pair_separator, value_separator, command])


def fish(_completer, ctxt, _trace, pair_separator, value_separator, command):
    '''Implement key_value_list_exec for fish'''
    func = ctxt.helpers.use_function('key_value_list_exec')
    return FishCompletionCommand(
        ctxt, [func, pair_separator, value_separator, command])


def zsh(_completer, ctxt, _trace, pair_separator, value_separator, command):
    '''Implement key_value_list_exec for zsh'''
    func = ctxt.helpers.use_function('key_value_list_exec')
    return ZshComplFunc(
        ctxt, [func, pair_separator, value_separator, command],
        needs_braces=True)
